{
  "majorDimension": "ROWS",
  "range": "log!C2",
  "values": [
    [
      "=LET(
  mid, TRIM($D$1),
  sids, A2:A,
  names, B2:B,
  sess_all, IMPORTRANGE("13F_0lX9bdndKzRXwgdYyWFQNhYG5828FM8EWsgieGgE","session!A2:C"),
  ts_all, 'フォームの回答 2'!A2:A,
  nm_all, 'フォームの回答 2'!C2:C,
  MAP(
    sids, names,
    LAMBDA(sid, nm,
      IF(
        OR(sid="", nm=""),
        "",
        IF(
          NOT(REGEXMATCH(sid, "_"&mid&"$")),
          "",
          LET(
            st, XLOOKUP(sid, INDEX(sess_all,,1), INDEX(sess_all,,2)),
            lt, XLOOKUP(sid, INDEX(sess_all,,1), INDEX(sess_all,,3)),
            ok, IFERROR(COUNTIFS(nm_all, nm, ts_all, ">="&st, ts_all, "<="&lt), 0),
            IF(ok>0, "出席", "欠席")
          )
        )
      )
    )
  )
)"
    ]
  ]
}

